UPDATE tbl_card_bill
SET due_date         = #{dueDate},
    bill_status_code = #{billStatusCode},
    bill_status_name = #{billStatusName},
    total_amount     = #{totalAmount},
    paid_amount      = #{paidAmount},
    raw_json         = #{rawJson}
WHERE card_id = #{cardId}
  AND billing_month = #{billingMonth}
